effects.fragment:
float l__phase = 0.5 + 0.5 * sin(u_time * u__pulse + v_tex_coord.y * 7.0);
float l__radius = length(v_tex_coord - vec2(0.5));
float l__veil = clamp(1.0 - l__radius * (1.1 + u__edge), 0.0, 1.0);
float l__luma = dot(gl_FragColor.rgb, vec3(0.2126, 0.7152, 0.0722));
vec3 l__spectral = mix(vec3(l__luma), vec3(l__luma) * u__tint, 0.78);
float l__mix = clamp(u__intensity * (0.72 + 0.28 * l__phase) * (0.72 + 0.28 * l__veil), 0.0, 1.0);
gl_FragColor.rgb = mix(gl_FragColor.rgb, l__spectral, l__mix);
gl_FragColor.a *= clamp(1.0 - u__fade * u__intensity * (0.65 + 0.35 * l__phase), 0.0, 1.0);

float l__beat = pow(0.5 + 0.5 * sin(u_time * u__speed), 3.0);
float l__band = 0.5 + 0.5 * sin(v_tex_coord.y * 310.0 + u_time * u__speed * 9.0);
vec3 l__contrast = (gl_FragColor.rgb - 0.5) * u__contrast + 0.5;
vec3 l__blood = l__contrast * vec3(1.0 + u__blood * 0.38, 1.0 - u__blood * 0.26, 1.0 - u__blood * 0.34);
float l__mix = clamp(u__intensity * (0.76 + 0.24 * l__beat), 0.0, 1.0);
gl_FragColor.rgb = mix(gl_FragColor.rgb, l__blood, l__mix);
gl_FragColor.rgb *= 1.0 - u__intensity * u__bands * l__band;

float l__luma = dot(gl_FragColor.rgb, vec3(0.2126, 0.7152, 0.0722));
float l__mask = 1.0 - smoothstep(u__threshold - u__softness, u__threshold + u__softness, l__luma);
float l__mix = clamp(u__intensity * l__mask, 0.0, 1.0);
gl_FragColor.rgb = mix(gl_FragColor.rgb, u__ink * (0.55 + 0.45 * l__luma), l__mix);
